content.text:
{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "partial",
      "summary_quote": "The definition of \"authorizer\" would name local boards of education, the commission, and the achievement school district.",
      "rationale": "Names all three entities but omits their defining role in approval, renewal, and revocation decisions."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "A new definition of \"replication\" would mean opening one or more charter schools with the same academic focus as an existing charter school run by a sponsor or governing body.",
      "rationale": "Conveys the definition's substantive elements; the replication process is described separately."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "Sponsors would apply to the local board, or to the commission where the chapter allows direct application.",
      "rationale": "Conveys the application requirement and the condition for applying directly to the commission without narrowing the schools covered."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "Letters of intent would go to the commission",
      "rationale": "Identifies the affected application step and its reassignment to the commission."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "Letters of intent would go to the commission, which must post them on its website within 10 days.",
      "rationale": "Conveys the commission's website-posting obligation and ten-day deadline following receipt."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "Sponsors would apply to the local board, or to the commission where the chapter allows direct application. Letters of intent would go to the commission, which must post them on its website within 10 days. Applications would be due February 1 of the year before opening, on a template from the state board in coordination with the commission.",
      "rationale": "Conveys the filing destination, deadline relative to opening, and required template's developers."
    },
    {
      "proposition_id": "P7",
      "status": "full",
      "summary_quote": "Authorizers must report each application to the commission within 10 days.",
      "rationale": "Conveys the reporting actor, recipient, scope, and receipt-based deadline."
    },
    {
      "proposition_id": "P8",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "The summary does not identify the deletion of § 49-13-108(b)(4); its generic deletion language does not identify this target."
    },
    {
      "proposition_id": "P9",
      "status": "partial",
      "summary_quote": "Some provisions would start January 1, 2021.",
      "rationale": "Gives the replacement date but does not identify § 49-13-108(b)(5) or the repeal-contingent language being replaced."
    },
    {
      "proposition_id": "P10",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "The general reference to agency substitutions does not identify the amendment to § 49-13-108(b)(5)(D)."
    },
    {
      "proposition_id": "P11",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "Does not identify either addition of the commission to § 49-13-108(g)."
    },
    {
      "proposition_id": "P12",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "Does not describe narrowing the applicability language to subsections (b)–(d)."
    },
    {
      "proposition_id": "P13",
      "status": "full",
      "summary_quote": "Starting July 1, 2025, if the commission overturns a local board's denial three times within three consecutive years, then for the next five years any sponsor in that school district may apply directly to the commission.",
      "rationale": "Conveys the start date, three-overturn trigger, district scope, and ensuing five-year direct-application window."
    },
    {
      "proposition_id": "P14",
      "status": "partial",
      "summary_quote": "The commission must rule within 90 days, or the application is deemed approved.",
      "rationale": "Conveys the deadline and deemed approval but omits the completed-application receipt trigger and the requirement to act by resolution at a meeting."
    },
    {
      "proposition_id": "P15",
      "status": "full",
      "summary_quote": "If it denies an application, it must give written, objective reasons. The sponsor then has 30 days to amend, and the commission has 60 days to decide, or the amended application is deemed approved.",
      "rationale": "Conveys the denial requirements, sequential amendment and decision periods, and deemed approval."
    },
    {
      "proposition_id": "P16",
      "status": "full",
      "summary_quote": "If it approves, the commission becomes both authorizer and local education agency for that school.",
      "rationale": "Expressly conveys both roles resulting from commission approval."
    },
    {
      "proposition_id": "P17",
      "status": "full",
      "summary_quote": "Its decision is final and cannot be appealed.",
      "rationale": "Expressly conveys finality and the appeal bar for these direct applications."
    },
    {
      "proposition_id": "P18",
      "status": "full",
      "summary_quote": "After the five years, sponsors must apply to the local board again unless the conditions are met again.",
      "rationale": "Conveys the return to local-board applications and the exception for a renewed qualifying trigger."
    },
    {
      "proposition_id": "P19",
      "status": "full",
      "summary_quote": "Public colleges and universities in Tennessee could apply to the local board or directly to the commission.",
      "rationale": "Conveys the eligible institutions and both application routes; the general application requirements are described earlier."
    },
    {
      "proposition_id": "P20",
      "status": "full",
      "summary_quote": "A charter school they sponsor could give enrollment preference to children of their employees or governing board members, up to 25% of total enrollment.",
      "rationale": "Conveys the institution-sponsored school limitation, eligible children, and enrollment cap."
    },
    {
      "proposition_id": "P21",
      "status": "partial",
      "summary_quote": "The commission would set timelines and the appeal process for charter amendment petitions, and its denials of amendments could not be appealed.",
      "rationale": "Conveys commission control over timelines and appeals, but omits the governing body's right to petition its authorizer and the condition that the commission itself be the authorizer for the appeal bar."
    },
    {
      "proposition_id": "P22",
      "status": "partial",
      "summary_quote": "Governing bodies could petition for voluntary early termination.",
      "rationale": "Conveys voluntary termination before expiration but does not identify the authorizer as the petition recipient."
    },
    {
      "proposition_id": "P23",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "Does not describe removal of the § 49-13-142(d) exception from § 49-13-111(a)(4)."
    },
    {
      "proposition_id": "P24",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "The generic agency-shift language does not identify the amendment to § 49-13-116(a)."
    },
    {
      "proposition_id": "P25",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "Does not identify the department-to-commission substitution in § 49-13-116(b)."
    },
    {
      "proposition_id": "P26",
      "status": "partial",
      "summary_quote": "The commission would post certain annual information online.",
      "rationale": "Conveys an annual online-publication duty but leaves the covered information unidentified rather than tying it to § 49-13-116(b)."
    },
    {
      "proposition_id": "P27",
      "status": "partial",
      "summary_quote": "The commissioner of education would produce an annual charter school report.",
      "rationale": "Conveys the actor and annual report but omits enrollment, geographic distribution, and the required performance evidence."
    },
    {
      "proposition_id": "P28",
      "status": "partial",
      "summary_quote": "Each authorizer would send an annual report by January 1 to the state board and post it online. It would cover each school's status, services the authorizer provided, and a performance report.",
      "rationale": "Conveys the deadline, submission, publication, and broad contents, but omits the specified status categories and explanations, the charter-agreement performance framework, and the report's addition to the annual audit."
    },
    {
      "proposition_id": "P29",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "Does not identify the substitution in § 49-13-121(a) or its consultation requirement."
    },
    {
      "proposition_id": "P30",
      "status": "full",
      "summary_quote": "Authorizers must report renewal applications to the commission within 10 days.",
      "rationale": "Conveys the reporting obligation, recipient, and ten-day deadline for renewal applications."
    },
    {
      "proposition_id": "P31",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "Describing annual reports does not convey replacement of 'progress reports' in § 49-13-121(d)."
    },
    {
      "proposition_id": "P32",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "Does not identify the deletion of § 49-13-121(e)."
    },
    {
      "proposition_id": "P33",
      "status": "partial",
      "summary_quote": "Some provisions would start January 1, 2021.",
      "rationale": "Gives the replacement date but does not identify § 49-13-121(f) or the repeal-contingent language being replaced."
    },
    {
      "proposition_id": "P34",
      "status": "partial",
      "summary_quote": "If the commission approves a renewal on appeal, or in certain achievement school district situations, the renewed charter would last at least five and no more than ten academic years, set by commission resolution.",
      "rationale": "Conveys the term range and resolution requirement but omits that the appeal is from a local board and that the school and commission must enter the renewed agreement."
    },
    {
      "proposition_id": "P35",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "Does not identify the addition of the commission to § 49-13-121(i)."
    },
    {
      "proposition_id": "P36",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "The generic agency-shift language does not identify the amendment to § 49-13-121(k)."
    },
    {
      "proposition_id": "P37",
      "status": "partial",
      "summary_quote": "If the commission approves a renewal on appeal, or in certain achievement school district situations, the renewed charter would last at least five and no more than ten academic years, set by commission resolution.",
      "rationale": "Conveys the term range and commission resolution but does not identify the qualifying statutory renewal situations or the required agreement between the school and commission."
    },
    {
      "proposition_id": "P38",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "Does not identify the addition of the commission to § 49-13-122(g)."
    },
    {
      "proposition_id": "P39",
      "status": "partial",
      "summary_quote": "Local districts that collect authorizer fees must report amounts and uses to the state board by December 1",
      "rationale": "Conveys the reporting entities, recipient, deadline, and broad contents, but omits that the report covers total fees collected in the previous school year."
    },
    {
      "proposition_id": "P40",
      "status": "partial",
      "summary_quote": "the state board would post them by December 11.",
      "rationale": "Conveys publication by the deadline but omits the board's duty to create a standard reporting template."
    },
    {
      "proposition_id": "P41",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "The generic agency-shift language does not identify the amendment to § 49-13-133(b)."
    },
    {
      "proposition_id": "P42",
      "status": "full",
      "summary_quote": "section 49-13-142 would be repealed.",
      "rationale": "Explicitly identifies the section deleted."
    },
    {
      "proposition_id": "P43",
      "status": "full",
      "summary_quote": "The state board would also provide the model performance framework",
      "rationale": "Identifies the state board's model-framework responsibility, which the bill links to § 49-13-143(a)."
    },
    {
      "proposition_id": "P44",
      "status": "partial",
      "summary_quote": "The state board would also provide the model performance framework, which authorizers without their own must adopt.",
      "rationale": "Conveys mandatory adoption but omits that the requirement also applies when an authorizer's existing framework does not cover all its schools."
    },
    {
      "proposition_id": "P45",
      "status": "partial",
      "summary_quote": "A governing body with at least one charter school that has operated a full school year could apply to replicate in its current district, either to the local board or directly to the commission.",
      "rationale": "Conveys the operating-history requirement, district restriction, and routes, but omits qualifying authorization by a local board or commission and measurement of the full year at letter-of-intent submission."
    },
    {
      "proposition_id": "P46",
      "status": "full",
      "summary_quote": "The state board, in consultation with the commission, would create the application form.",
      "rationale": "Conveys both agencies' roles in developing the replication application form."
    },
    {
      "proposition_id": "P47",
      "status": "partial",
      "summary_quote": "The direct-to-commission process uses the same 90-day, 30-day, and 60-day deadlines, deemed-approval rules, written-denial rules, commission-as-authorizer rule, and no-appeal rule.",
      "rationale": "Incorporates the 90-day decision and deemed-approval rules but omits the completed-application receipt trigger and action by resolution at a meeting."
    },
    {
      "proposition_id": "P48",
      "status": "full",
      "summary_quote": "The direct-to-commission process uses the same 90-day, 30-day, and 60-day deadlines, deemed-approval rules, written-denial rules, commission-as-authorizer rule, and no-appeal rule.",
      "rationale": "Incorporates the previously described written, objective denial grounds, amendment period, decision period, and deemed approval."
    },
    {
      "proposition_id": "P49",
      "status": "partial",
      "summary_quote": "The direct-to-commission process uses the same 90-day, 30-day, and 60-day deadlines, deemed-approval rules, written-denial rules, commission-as-authorizer rule, and no-appeal rule.",
      "rationale": "Identifies the commission as authorizer but does not expressly carry over its separate role as LEA for the replicated school."
    },
    {
      "proposition_id": "P50",
      "status": "full",
      "summary_quote": "The direct-to-commission process uses the same 90-day, 30-day, and 60-day deadlines, deemed-approval rules, written-denial rules, commission-as-authorizer rule, and no-appeal rule.",
      "rationale": "Applies the previously stated finality and no-appeal rule to direct replication decisions."
    },
    {
      "proposition_id": "P51",
      "status": "full",
      "summary_quote": "Applying to the local board through the existing process would remain allowed.",
      "rationale": "Conveys preservation of the local-board replication application route."
    },
    {
      "proposition_id": "P52",
      "status": "full",
      "summary_quote": "The act takes effect July 1, 2025.",
      "rationale": "States the effective date exactly."
    }
  ]
}
